def verify_pa():
    """1.72.626 (HAD-684): the sign-up route answers and refuses bad input; nothing is stored (each call fails validation before any write
    and before the rate counters). Runner POSTs carry auth (the uPress edge answers a cookieless runner POST with nginx 405)."""
    B = {'phone': '0501234567', 'email': 'runner@example.com', 'consent': 1}
    cases = [({'id': 0}, 'page'), ({'id': 2415, 'phone': '123'}, 'phone'), ({'id': 2415, 'email': 'not-an-email'}, 'email'), ({'id': 2415, 'consent': 0}, 'consent')]
    ok = True
    for over, want in cases:
        body = dict(B); body.update(over)
        try:
            s, j = req('POST', '/wp-json/nadlan/v1/price-alert', body=body, auth=True)
        except Exception as e:  # noqa: BLE001
            s, j = str(e)[:60], {}
        good = s == 400 and isinstance(j, dict) and j.get('ok') is False and j.get('error') == want
        print(f"[price-alert] {'OK ' if good else 'BAD'} {want}: {s} {j if not good else ''}")
        ok = ok and good
    return ok


