def ttfb(path):
    t0 = time.time()
    r = urllib.request.Request(BASE + path + ("&" if "?" in path else "?") + "nlt=" + secrets.token_hex(4), headers={"User-Agent": UA})
    with urllib.request.urlopen(r, timeout=60) as resp:
        resp.read(1)
        first = time.time() - t0
        resp.read()
        return resp.status, round(first, 2)


