def verify_pages(tag):
    bad = []
    for chk in CHECKS:
        path, need, never = chk[:3]
        never_html = chk[3] if len(chk) > 3 else []
        sep = "&" if "?" in path else "?"
        try:
            s, html = page(path + sep + "nlv=" + tag)
            if s in (502, 503, 504):
                print(f"[page] gateway {s} on {path[:70]}: one more look in 8 s")
                time.sleep(8)
                s, html = page(path + sep + "nlv=" + tag + "r")
        except Exception as e:  # a timeout is a failed check, not a crash that skips the rollback
            print(f"[page] BAD --- {path[:70]} {e}")
            bad.append(path)
            continue
        body = body_of(html)
        miss = [n for n in need if n not in html]
        hit = [n for n in never if n in body] + ["html:" + n for n in never_html if n in html]
        if path in H1_EXACTLY_ONE and body.count("<h1") != 1:
            hit.append("h1 x%d" % body.count("<h1"))
        ok = s == 200 and not miss and not hit and "Fatal error" not in body and "critical error" not in body
        print(f"[page] {'OK ' if ok else 'BAD'} {s} {path[:70]} missing={miss} forbidden={hit}")
        if not ok:
            bad.append(path)
    return bad


def wait_version(want, secs=75):
    t0 = time.time()
    last = None
    while time.time() - t0 < secs:
        try:
            s, h2 = req("GET", "/wp-json/nadlan/v1/health?nlv=" + str(int(time.time())), auth=False)
            last = h2.get("version") if isinstance(h2, dict) else s
            if s == 200 and isinstance(h2, dict) and h2.get("version") == want and h2.get("status") == "ok":
                print(f"[health] {want} ok after {int(time.time() - t0)}s")
                return True
        except Exception as e:
            last = str(e)
        time.sleep(4)
    print(f"[health] still {last} after {secs}s")
    return False


def rollback(created_any, posts_state=None):
    for _kind, _m in reversed(UNDO):  # 1.72.626: the writes that are not files
        try:
            if _kind == "snippet" and LIVE_SNIPPET.get("code"):
                _s1, _ = snip("PUT", "/661", {"name": "x-catalog-plus", "code": LIVE_SNIPPET["code"], "scope": "global", "active": False})
                _s2, _ = snip("PUT", "/661/activate", {})
                print("[rollback] snippet 661 restored", _s1, _s2)
            elif _kind == "page":
                print("[rollback] page 73", ops({"pcontent": {"id": 73, "force": 1, "b64": base64.b64encode(UR.PAGE["before"]).decode(), "md5": UR.PAGE["before_md5"]}}, "page 73 restore").get("pcontent"))
            elif _kind == "adv":  # 1.72.626: the advisor key and pages are removed with the module
                print("[rollback] advisor options cleared", ops({"adv_cfg": {"clear": 1}}, "advisor options clear").get("adv_cfg"))
            elif _kind == "meta":
                print("[rollback] meta", _m["id"], _m["key"], ops({"pmeta": {"id": _m["id"], "key": _m["key"], "force": 1, "b64": base64.b64encode(_m["before"]).decode(), "md5": _m["before_md5"]}}, "meta restore").get("pmeta"))
        except BaseException as _e:  # keep undoing the rest; the record shows what could not be undone
            print("[rollback] COULD NOT UNDO", _kind, _e)
    print("[rollback] restoring .bak626 files")
    for rel in list(dict.fromkeys(["nadlan-config.php"] + PHP_RELS + [r for r in FILES if r not in NEWFILES])):  # 1.72.626: once each, main file first
        print("  ", rel, ops({"restore": rel}, "restore " + rel).get("restore"))
    for rel in sorted(NEWFILES):
        ops({"unlink": rel}, "unlink " + rel)
    print("   new files removed:", len(NEWFILES))
    if posts_state:
        print("[rollback] posts:", json.dumps(ops({"posts_restore": posts_state}, "posts restore").get("posts_restore"), ensure_ascii=False))
    ops({"purge": 1}, "purge")


